{"status":"candidate","chosen_option":"trie_dp","assumptions":["The input follows the stated format and the solution is compiled as C++17."],"observations":[{"statement":"There are at most 30 characters to scan from each reachable text position, so trie-based DP takes O(30n) matching time after construction.","source_ids":["task"]},{"statement":"Duplicate spellings can be represented by storing their minimum cost at the trie terminal.","source_ids":["task"]},{"statement":"The public examples expect outputs 3 and -1, respectively.","source_ids":["public1","public2"]}],"artifact":{"code":"#include <bits/stdc++.h>
using namespace std;

struct Node {
    int next[26];
    long long cost;
    Node() : cost(LLONG_MAX) { fill(begin(next), end(next), -1); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string text;
    int d;
    if (!(cin >> text >> d)) return 0;

    vector<Node> trie(1);
    for (int i = 0; i < d; ++i) {
        string word;
        long long cost;
        cin >> word >> cost;
        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (trie[node].next[c] == -1) {
                trie[node].next[c] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            node = trie[node].next[c];
        }
        trie[node].cost = min(trie[node].cost, cost);
    }

    const long long INF = (1LL << 62);
    int n = static_cast<int>(text.size());
    vector<long long> dp(n + 1, INF);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        if (dp[i] == INF) continue;
        int node = 0;
        for (int j = i; j < n && j < i + 30; ++j) {
            int c = text[j] - 'a';
            node = trie[node].next[c];
            if (node == -1) break;
            if (trie[node].cost != LLONG_MAX) {
                dp[j + 1] = min(dp[j + 1], dp[i] + trie[node].cost);
            }
        }
    }

    cout << (dp[n] == INF ? -1 : dp[n]) << '\n';
    return 0;
}"} }
